package com.tiviloom.mobile;
import java.io.*;import java.nio.charset.StandardCharsets;import java.text.*;import java.util.*;import org.json.*;
public class EpgParserTest{static InputStream bytes(String s){return new ByteArrayInputStream(s.getBytes(StandardCharsets.UTF_8));}public static void main(String[] args)throws Exception{SimpleDateFormat f=new SimpleDateFormat("yyyyMMddHHmmss Z",Locale.US);f.setTimeZone(TimeZone.getTimeZone("UTC"));long now=System.currentTimeMillis();String xml="<tv><channel id='c'><display-name>A &amp; B</display-name></channel><programme channel='c' start='"+f.format(new Date(now-60000))+"' stop='"+f.format(new Date(now+3600000))+"'><title>Show</title></programme></tv>";JSONObject result=EpgParser.parse(bytes(xml),10000);if(result.getJSONArray("programs").length()!=1||!result.getJSONObject("names").getString("c").equals("A & B"))throw new AssertionError();boolean limit=false;try{EpgParser.parse(bytes(xml),10);}catch(IOException e){limit=true;}if(!limit)throw new AssertionError();boolean secure=false;try{EpgParser.parse(bytes("<!DOCTYPE tv [<!ENTITY xxe SYSTEM 'file:///etc/passwd'>]><tv/>"),10000);}catch(Exception e){secure=true;}if(!secure)throw new AssertionError();if(EpgParser.time("20261024010000 +0400")!=EpgParser.time("20261023210000 +0000"))throw new AssertionError();System.out.println("PASS native XMLTV parsing, entity decoding, size limit, XXE rejection and timezone conversion");}}
